//! Actions-only SAME original physical writer cancellation and actual socket
//! Drop/Join. These low-level IO cases do not create a Hosted/readiness grant.
use super::*;
use n::{im_inbox::{CursorSession,ReceivedAdmission},im_receipt_policy::NativeImReceiptConfig,account_test_support::TempDatabase};
#[path="im_read_status_io_tests.rs"]
mod manual_read_status;
fn original(temp:&TempDatabase,root:&str)->(AttemptOwner,Arc<n::account_runs::RunToken>){
    let line="app-account-0123456789abcdef0123456789abcdef";let mut cfg=n::account_config::tests::native_fixture(root,"127.0.0.1",1);cfg.credentials.sdk.expires_at_unix_seconds=None;cfg.profile.incoming=None;cfg.profile.client_ex=true;cfg.profile.native_receivers=Some(super::config(true));temp.database.with_conn(|c|n::account_store::create(c,line,&cfg,100)).unwrap();let run=Arc::new(temp.database.with_conn(|c|n::account_runs::register_runtime(c,line,1,&n::account_runtime::local_nonce().unwrap())).unwrap());let mut s=n::session::HostingSession::new(line.into());s.import(n::tests::imported(),100).unwrap();(s.begin_login(100).unwrap(),run)
}
fn status()->Vec<u8>{let mut w=Writer::new();w.boolean(true).unwrap();w.u32(1).unwrap();w.bytes(b"1_2").unwrap();w.properties(&[RpcProperty{key:n::im_status::PEER_READ,value:b"0"},RpcProperty{key:n::im_status::LATEST,value:b"1"}]).unwrap();w.i64(1).unwrap();w.bytes(b"").unwrap();w.finish().expose_to_transport().to_vec()}
async fn peer_reads(peer:&mut CommonPeer){peer_login(peer).await;let p=peer.next().await.unwrap();let id=query(&p,n::im_status::REFRESH_METHOD);peer.send(&[reply(id,&status())]).await;let p=peer.next().await.unwrap();let id=query(&p,n::im_data::RECV_METHOD);peer.send(&[reply(id,&received(&[1]))]).await;}
async fn permit(handle:&RuntimeHandle,original:&AttemptOwner,scope:&RpcConnectionScope,temp:&TempDatabase,run:Arc<n::account_runs::RunToken>,gate:Arc<ImReceiptGate>)->Arc<n::im_inbox::ReceivedWritePermit>{
    let commands=handle.command_handle();let r=bounded(commands.read_im(original,scope,refresh(),gate.clone())).await.unwrap();let mut c=CursorSession::from_refresh(run,gate.clone(),&r).unwrap();c.observe_refresh(&temp.database,&r).unwrap();let plan=c.next_gap(&temp.database).unwrap().unwrap();let r=bounded(commands.read_im(original,scope,plan.query(),gate)).await.unwrap();let s=c.commit_gap(&temp.database,&plan,&r).unwrap();let ReceivedAdmission::Fresh(p)=n::im_inbox::begin_received(temp.database.clone(),&s,&NativeImReceiptConfig{set_received:true}).unwrap()else{panic!("fresh receipt")};p
}
fn state(temp:&TempDatabase)->(i64,Option<i32>){temp.database.with_conn(|c|c.query_row("SELECT state,request_id FROM app_voice_im_read_receipts",[],|r|Ok((r.get(0)?,r.get(1)?))).map_err(|_|"fixture")).unwrap()}
async fn blocked(parent:bool){
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let p=router_policy(&cert.root,listener.local_addr().unwrap().port());let server=cert.server_config(&TLS13);let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;peer_reads(&mut peer).await;assert!(peer.next().await.is_none(),"no blocked write/replay leaves original stream");}).await});
    let temp=TempDatabase::new();let(original,run)=original(&temp,&cert.root);let mut conn=connected(&p,original.clone(),Instant::now()+Duration::from_secs(6)).await;let flag=Arc::new(AtomicBool::new(false));let pauses=n::common_runtime::tests::gate_im_read_write(conn.common.as_mut().unwrap(),flag.clone());let scope=conn.connection_scope();let(mut handle,mut events)=conn.attach().unwrap();auth(&handle,&mut events,&original,&scope,true).await;let gate=ImReceiptGate::fresh();let permit=permit(&handle,&original,&scope,&temp,run,gate.clone()).await;
    flag.store(true,Ordering::SeqCst);let commands=handle.command_handle();let mut sending=Box::pin(commands.write_received(&original,&scope,permit.clone()));assert!(tokio::time::timeout(Duration::from_millis(35),&mut sending).await.is_err());assert!(pauses.load(Ordering::SeqCst)>0);assert_eq!(state(&temp),(0,Some(4)));
    if parent{gate.retire();assert_eq!(bounded(sending).await.err(),Some(RuntimeError::Cancelled));}else{drop(sending);}
    bounded(scope.closed()).await;let release=bounded(handle.close()).await;assert!(release.io_released());assert_eq!(release.reason,RuntimeError::Cancelled);assert_eq!(state(&temp),(0,Some(4)));bounded(serving).await.unwrap();
}
#[tokio::test]async fn received_io_possible_partial_cancel_closes_same_scope_keeps_unknown_and_joins_original_socket(){Box::pin(blocked(false)).await;}
#[tokio::test]async fn received_io_parent_retirement_during_original_write_keeps_unknown_and_no_late_frame(){Box::pin(blocked(true)).await;}
#[tokio::test]
async fn received_io_fully_submitted_wait_drop_keeps_unknown_not_read_interest_and_releases_actual_owned_io(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let p=router_policy(&cert.root,listener.local_addr().unwrap().port());let server=cert.server_config(&TLS13);let(ready,seen)=oneshot::channel();let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;peer_reads(&mut peer).await;let p=peer.next().await.unwrap();assert_eq!(query(&p,n::im_data::SET_READ_METHOD),4);ready.send(()).unwrap();assert!(peer.next().await.is_none(),"unknown write is never replayed");}).await});
    let temp=TempDatabase::new();let(original,run)=original(&temp,&cert.root);let conn=connected(&p,original.clone(),Instant::now()+Duration::from_secs(6)).await;let scope=conn.connection_scope();let(mut handle,mut events)=conn.attach().unwrap();auth(&handle,&mut events,&original,&scope,true).await;let p=permit(&handle,&original,&scope,&temp,run,ImReceiptGate::fresh()).await;let commands=handle.command_handle();let mut writing=Box::pin(commands.write_received(&original,&scope,p.clone()));
    tokio::select!{r=writing.as_mut()=>panic!("peer did not reply to received write: {r:?}"),r=seen=>r.unwrap()};
    let submitted=async{while !p.has_submitted(){tokio::task::yield_now().await;}};tokio::select!{r=writing.as_mut()=>panic!("original result absent: {r:?}"),_=bounded(submitted)=>{}};assert_eq!(state(&temp),(0,Some(4)));drop(writing);bounded(scope.closed()).await;assert!(bounded(handle.close()).await.io_released());assert_eq!(state(&temp),(0,Some(4)));bounded(serving).await.unwrap();
}).await;}
